-- +goose Up
-- DSA-03 (docs/decisions.md Q-34): 4 ready-to-use TH/EN standard DSA templates — the same shape DPA-01's
-- own migration 00054 already took for "dpa". PLT-16's document composer already registers the "dsa" doc
-- type (internal/wiring.Docs, agreement.dsa.* permissions — read/create/update/publish already seeded to
-- LEGAL in the baseline RBAC) and already has its own generic, doc-type-agnostic template library
-- (internal/platform/docs/library.go's ListTemplates/CreateTemplate/PublishTemplate on platform.templates,
-- the same table/mechanism DPA-01/PNG-03 already used, language='mul' carries both th/en content in one
-- row as render.Content's own {"th": ..., "en": ...} shape). No new backend or frontend code: the existing
-- /documents/templates page already lets anyone holding agreement.dsa.update author/clone a "dsa"
-- template; this just seeds the module doc's own 4 named variants (one-way disclosure, two-way exchange,
-- government agency, research) so LEGAL has something ready to use/clone from day one, the same
-- "seed a draft flagged for legal review" move ORG-07/ROPA-09/PNG-03/DPIA-01/RTG-01/VEN-04/DPA-01 already
-- made — the clause wording here paraphrases ม.27 วรรคสอง/37(2)/24(1) from this feature's own module-doc
-- description, not an official legal source.
ALTER TABLE platform.templates NO FORCE ROW LEVEL SECURITY;

INSERT INTO platform.templates (tenant_id, template_type, code, name, language, content, version_no, status)
VALUES
(NULL, 'dsa', 'one_way', 'ข้อตกลงการแบ่งปันข้อมูลแบบส่งทางเดียว / One-Way Data Sharing Agreement', 'mul', $j${"th": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[ร่าง — ข้อความตัวอย่างนี้ต้องได้รับการทบทวนและอนุมัติจากฝ่ายกฎหมายก่อนใช้งานจริง]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "คู่สัญญาและบทบาท"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ข้อตกลงฉบับนี้ทำขึ้นระหว่าง "}, {"type": "mergeField", "attrs": {"key": "org_name_th"}}, {"type": "text", "text": " (\"ผู้เปิดเผยข้อมูล\") และ [ชื่อผู้รับข้อมูล] (\"ผู้รับข้อมูล\") สำหรับการส่งข้อมูลทางเดียว ตามมาตรา 27 แห่งพระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "วัตถุประสงค์และขอบเขตการเปิดเผยข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้เปิดเผยข้อมูลตกลงเปิดเผยข้อมูลส่วนบุคคลให้แก่ผู้รับข้อมูลเพื่อวัตถุประสงค์ [โปรดระบุวัตถุประสงค์] เท่านั้น ตามประเภทข้อมูลและระยะเวลาที่ระบุไว้ในภาคผนวก"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ฐานทางกฎหมายในการเปิดเผยข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "การเปิดเผยข้อมูลตามข้อตกลงนี้มีฐานทางกฎหมายตามมาตรา 24 หรือ 26 แห่งพระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 [โปรดระบุฐานที่ใช้] และผู้เปิดเผยข้อมูลได้บันทึกการเปิดเผยนี้ไว้ในบันทึกรายการตามมาตรา 39"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อจำกัดการใช้ข้อมูลของผู้รับข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้รับข้อมูลต้องใช้ข้อมูลส่วนบุคคลเฉพาะตามวัตถุประสงค์ที่ได้รับแจ้งเท่านั้น ห้ามใช้หรือเปิดเผยต่อเกินกว่าวัตถุประสงค์ที่แจ้งไว้ตามมาตรา 27"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "มาตรการความปลอดภัยของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ทั้งสองฝ่ายต้องจัดให้มีมาตรการรักษาความมั่นคงปลอดภัยที่เหมาะสมตามมาตรา 37(2) และประกาศมาตรการความปลอดภัย พ.ศ. 2565 [โปรดระบุมาตรการที่ใช้]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การแจ้งเหตุละเมิดข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้รับข้อมูลต้องแจ้งเหตุการละเมิดข้อมูลส่วนบุคคลที่เกี่ยวข้องกับข้อมูลที่ได้รับให้ผู้เปิดเผยข้อมูลทราบโดยไม่ชักช้าภายใน [โปรดระบุระยะเวลา] นับแต่ทราบเหตุ"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "สิทธิของเจ้าของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้รับข้อมูลต้องให้ความช่วยเหลือผู้เปิดเผยข้อมูลในการตอบสนองต่อคำขอใช้สิทธิของเจ้าของข้อมูลส่วนบุคคลที่เกี่ยวข้องกับข้อมูลที่ได้รับตามที่กฎหมายกำหนด"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การคืนหรือทำลายข้อมูลเมื่อสิ้นสุดข้อตกลง"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เมื่อสิ้นสุดข้อตกลงนี้หรือบรรลุวัตถุประสงค์แล้ว ผู้รับข้อมูลต้องคืนหรือทำลายข้อมูลส่วนบุคคลทั้งหมดตามที่ผู้เปิดเผยข้อมูลกำหนด เว้นแต่กฎหมายกำหนดให้ต้องเก็บไว้ต่อไป"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อมูลติดต่อเจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " อีเมล "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}, "en": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[DRAFT — this sample text must be reviewed and approved by Legal before real use]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Parties and roles"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This agreement is made between "}, {"type": "mergeField", "attrs": {"key": "org_name_en"}}, {"type": "text", "text": " (the \"Disclosing Party\") and [receiving party name] (the \"Receiving Party\") for a one-way data sharing arrangement under section 27 of the Personal Data Protection Act B.E. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Purpose and scope of disclosure"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Disclosing Party agrees to disclose personal data to the Receiving Party solely for [please specify purpose], for the data categories and duration set out in the annex."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Legal basis for disclosure"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Disclosure under this agreement relies on a legal basis under section 24 or 26 of the Personal Data Protection Act B.E. 2562 [please specify the basis used], and the Disclosing Party has recorded this disclosure in its section 39 record of processing activities."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Restrictions on the Receiving Party's use of data"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Receiving Party shall use the personal data only for the notified purpose and shall not use or further disclose it beyond that purpose, under section 27."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Security measures"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Both parties shall implement appropriate security measures under section 37(2) and the 2022 Security Measures Notification. [Please specify the measures used]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Personal data breach notification"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Receiving Party shall notify the Disclosing Party of a personal data breach concerning the received data without delay, within [please specify a timeframe] of becoming aware of it."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data subject rights"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Receiving Party shall assist the Disclosing Party in responding to data subject rights requests concerning the received data as required by law."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Return or destruction of data on termination"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On termination of this agreement or once its purpose is fulfilled, the Receiving Party shall return or destroy all personal data as directed by the Disclosing Party, unless retention is required by law."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data Protection Officer contact"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Data Protection Officer: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " e-mail "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}}$j$::jsonb, 1, 'published'),
(NULL, 'dsa', 'two_way', 'ข้อตกลงการแบ่งปันข้อมูลแบบแลกเปลี่ยนสองทาง / Two-Way Data Exchange Agreement', 'mul', $j${"th": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[ร่าง — ข้อความตัวอย่างนี้ต้องได้รับการทบทวนและอนุมัติจากฝ่ายกฎหมายก่อนใช้งานจริง]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "คู่สัญญาและบทบาท"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ข้อตกลงฉบับนี้ทำขึ้นระหว่าง "}, {"type": "mergeField", "attrs": {"key": "org_name_th"}}, {"type": "text", "text": " (\"ฝ่ายที่หนึ่ง\") และ [ชื่อคู่สัญญาอีกฝ่าย] (\"ฝ่ายที่สอง\") สำหรับการแลกเปลี่ยนข้อมูลสองทาง ตามมาตรา 27 แห่งพระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "วัตถุประสงค์และขอบเขตการแลกเปลี่ยนข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ทั้งสองฝ่ายตกลงแลกเปลี่ยนข้อมูลส่วนบุคคลระหว่างกันเพื่อวัตถุประสงค์ [โปรดระบุวัตถุประสงค์] โดยแต่ละฝ่ายเป็นทั้งผู้เปิดเผยและผู้รับข้อมูลตามรายละเอียดในภาคผนวก"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "บทบาทและความรับผิดชอบของแต่ละฝ่าย"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "แต่ละฝ่ายมีสถานะเป็นผู้ควบคุมข้อมูลส่วนบุคคลของตนเองสำหรับข้อมูลที่ตนเปิดเผย และต้องรับผิดชอบตามหน้าที่ของผู้ควบคุมข้อมูลเมื่อได้รับข้อมูลจากอีกฝ่าย"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ฐานทางกฎหมายในการแลกเปลี่ยนข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "การแลกเปลี่ยนข้อมูลตามข้อตกลงนี้มีฐานทางกฎหมายตามมาตรา 24 หรือ 26 [โปรดระบุฐานที่ใช้] และทั้งสองฝ่ายต้องบันทึกการเปิดเผย/รับข้อมูลไว้ในบันทึกรายการของตนตามมาตรา 39"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อจำกัดการใช้ข้อมูลที่ได้รับ"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "แต่ละฝ่ายต้องใช้ข้อมูลที่ได้รับจากอีกฝ่ายเฉพาะตามวัตถุประสงค์ที่ตกลงกันเท่านั้น ตามมาตรา 27"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "มาตรการความปลอดภัยของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ทั้งสองฝ่ายต้องจัดให้มีมาตรการรักษาความมั่นคงปลอดภัยที่เหมาะสมตามมาตรา 37(2) และประกาศมาตรการความปลอดภัย พ.ศ. 2565 [โปรดระบุมาตรการที่ใช้]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การแจ้งเหตุละเมิดข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ฝ่ายที่พบเหตุการละเมิดข้อมูลส่วนบุคคลที่เกี่ยวข้องกับข้อมูลที่ได้รับจากอีกฝ่ายต้องแจ้งให้อีกฝ่ายทราบโดยไม่ชักช้าภายใน [โปรดระบุระยะเวลา]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "สิทธิของเจ้าของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ทั้งสองฝ่ายต้องให้ความช่วยเหลือซึ่งกันและกันในการตอบสนองต่อคำขอใช้สิทธิของเจ้าของข้อมูลส่วนบุคคลตามที่กฎหมายกำหนด"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การยุติการแลกเปลี่ยนข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เมื่อสิ้นสุดข้อตกลงนี้ แต่ละฝ่ายต้องยุติการใช้ข้อมูลที่ได้รับจากอีกฝ่าย และคืนหรือทำลายข้อมูลดังกล่าวตามที่ตกลงกัน เว้นแต่กฎหมายกำหนดให้ต้องเก็บไว้ต่อไป"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อมูลติดต่อเจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " อีเมล "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}, "en": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[DRAFT — this sample text must be reviewed and approved by Legal before real use]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Parties and roles"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This agreement is made between "}, {"type": "mergeField", "attrs": {"key": "org_name_en"}}, {"type": "text", "text": " (\"Party A\") and [other party name] (\"Party B\") for a two-way data exchange under section 27 of the Personal Data Protection Act B.E. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Purpose and scope of the exchange"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Both parties agree to exchange personal data with each other for [please specify purpose], with each party acting as both a disclosing and a receiving party as set out in the annex."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Roles and responsibilities of each party"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Each party is its own controller for the data it discloses, and is responsible as a controller for the data it receives from the other party."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Legal basis for the exchange"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The exchange under this agreement relies on a legal basis under section 24 or 26 [please specify the basis used], and both parties shall record the disclosure/receipt in their own section 39 records."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Restrictions on use of received data"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Each party shall use data received from the other party only for the agreed purpose, under section 27."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Security measures"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Both parties shall implement appropriate security measures under section 37(2) and the 2022 Security Measures Notification. [Please specify the measures used]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Personal data breach notification"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A party that discovers a personal data breach concerning data received from the other party shall notify that party without delay, within [please specify a timeframe]."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data subject rights"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Both parties shall assist each other in responding to data subject rights requests as required by law."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Ending the exchange"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On termination of this agreement, each party shall stop using data received from the other party and return or destroy it as agreed, unless retention is required by law."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data Protection Officer contact"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Data Protection Officer: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " e-mail "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}}$j$::jsonb, 1, 'published'),
(NULL, 'dsa', 'government', 'ข้อตกลงการแบ่งปันข้อมูลกับหน่วยงานรัฐ / Government Agency Data Sharing Agreement', 'mul', $j${"th": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[ร่าง — ข้อความตัวอย่างนี้ต้องได้รับการทบทวนและอนุมัติจากฝ่ายกฎหมายก่อนใช้งานจริง]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "คู่สัญญาและบทบาท"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ข้อตกลงฉบับนี้ทำขึ้นระหว่าง "}, {"type": "mergeField", "attrs": {"key": "org_name_th"}}, {"type": "text", "text": " (\"ผู้ควบคุมข้อมูล\") และ [ชื่อหน่วยงานรัฐ] (\"หน่วยงานรัฐ\") สำหรับการแบ่งปันข้อมูลกับหน่วยงานของรัฐ ตามมาตรา 27 แห่งพระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "วัตถุประสงค์และอำนาจทางกฎหมายของหน่วยงานรัฐ"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "หน่วยงานรัฐเปิดเผยหรือขอรับข้อมูลส่วนบุคคลภายใต้ข้อตกลงนี้โดยอาศัยอำนาจตามกฎหมาย [โปรดระบุกฎหมายที่ให้อำนาจ] เพื่อวัตถุประสงค์ [โปรดระบุวัตถุประสงค์]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ฐานทางกฎหมายในการเปิดเผยข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "การเปิดเผยข้อมูลให้แก่หน่วยงานรัฐตามข้อตกลงนี้มีฐานทางกฎหมายตามมาตรา 24 หรือ 26 หรือเป็นกรณีที่ได้รับยกเว้นความยินยอมตามกฎหมายเฉพาะของหน่วยงานรัฐนั้น [โปรดระบุฐานที่ใช้] และต้องบันทึกการเปิดเผยที่ได้รับยกเว้นไว้ตามมาตรา 39"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อจำกัดการใช้ข้อมูลของหน่วยงานรัฐ"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "หน่วยงานรัฐต้องใช้ข้อมูลส่วนบุคคลเฉพาะตามอำนาจหน้าที่และวัตถุประสงค์ที่ระบุไว้ ห้ามใช้หรือเปิดเผยต่อเกินกว่าที่กฎหมายให้อำนาจไว้ตามมาตรา 27"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "มาตรการความปลอดภัยของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ทั้งสองฝ่ายต้องจัดให้มีมาตรการรักษาความมั่นคงปลอดภัยที่เหมาะสมตามมาตรา 37(2) และประกาศมาตรการความปลอดภัย พ.ศ. 2565 [โปรดระบุมาตรการที่ใช้]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การแจ้งเหตุละเมิดข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ฝ่ายที่พบเหตุการละเมิดข้อมูลส่วนบุคคลที่เกี่ยวข้องกับข้อมูลตามข้อตกลงนี้ต้องแจ้งให้อีกฝ่ายทราบโดยไม่ชักช้าภายใน [โปรดระบุระยะเวลา]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "สิทธิของเจ้าของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "หน่วยงานรัฐต้องให้ความช่วยเหลือในการตอบสนองต่อคำขอใช้สิทธิของเจ้าของข้อมูลส่วนบุคคลตามที่กฎหมายกำหนด เว้นแต่มีข้อยกเว้นตามกฎหมายเฉพาะ"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ระยะเวลาเก็บรักษาและการทำลายข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ข้อมูลส่วนบุคคลที่ได้รับหรือเปิดเผยตามข้อตกลงนี้ต้องเก็บรักษาและทำลายตามระยะเวลาที่กฎหมายหรือระเบียบของหน่วยงานรัฐกำหนด [โปรดระบุระยะเวลา]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อมูลติดต่อเจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " อีเมล "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}, "en": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[DRAFT — this sample text must be reviewed and approved by Legal before real use]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Parties and roles"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This agreement is made between "}, {"type": "mergeField", "attrs": {"key": "org_name_en"}}, {"type": "text", "text": " (the \"Controller\") and [government agency name] (the \"Government Agency\") for data sharing with a government agency under section 27 of the Personal Data Protection Act B.E. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Purpose and the government agency's legal authority"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The government agency discloses or requests personal data under this agreement under the authority of [please specify the enabling law], for [please specify purpose]."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Legal basis for disclosure"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Disclosure to the government agency under this agreement relies on a legal basis under section 24 or 26, or on a consent exemption under that agency's own specific law [please specify the basis used], and any exempted disclosure shall be recorded under section 39."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Restrictions on the government agency's use of data"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The government agency shall use personal data only within its statutory powers and the stated purpose, and shall not use or further disclose it beyond what the law authorizes, under section 27."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Security measures"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Both parties shall implement appropriate security measures under section 37(2) and the 2022 Security Measures Notification. [Please specify the measures used]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Personal data breach notification"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A party that discovers a personal data breach concerning data under this agreement shall notify the other party without delay, within [please specify a timeframe]."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data subject rights"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The government agency shall assist in responding to data subject rights requests as required by law, unless a specific statutory exemption applies."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Retention period and destruction of data"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Personal data received or disclosed under this agreement shall be retained and destroyed according to the retention period set by law or the government agency's own regulations. [Please specify the period]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data Protection Officer contact"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Data Protection Officer: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " e-mail "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}}$j$::jsonb, 1, 'published'),
(NULL, 'dsa', 'research', 'ข้อตกลงการแบ่งปันข้อมูลเพื่อการวิจัย / Research Data Sharing Agreement', 'mul', $j${"th": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[ร่าง — ข้อความตัวอย่างนี้ต้องได้รับการทบทวนและอนุมัติจากฝ่ายกฎหมายก่อนใช้งานจริง]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "คู่สัญญาและบทบาท"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ข้อตกลงฉบับนี้ทำขึ้นระหว่าง "}, {"type": "mergeField", "attrs": {"key": "org_name_th"}}, {"type": "text", "text": " (\"ผู้เปิดเผยข้อมูล\") และ [ชื่อผู้วิจัย/สถาบัน] (\"ผู้วิจัย\") สำหรับการเปิดเผยข้อมูลเพื่อการวิจัย ตามมาตรา 27 และมาตรา 24(1) แห่งพระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "วัตถุประสงค์การวิจัย"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้เปิดเผยข้อมูลตกลงเปิดเผยข้อมูลส่วนบุคคลให้แก่ผู้วิจัยเพื่อใช้ในการศึกษาวิจัยทางวิชาการหรือสถิติ [โปรดระบุชื่อและรายละเอียดโครงการวิจัย] เท่านั้น"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ฐานทางกฎหมายในการเปิดเผยข้อมูลเพื่อการวิจัย"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "การเปิดเผยข้อมูลตามข้อตกลงนี้มีฐานทางกฎหมายเพื่อการศึกษาวิจัยหรือสถิติตามมาตรา 24(1) หรือฐานอื่นที่เกี่ยวข้อง [โปรดระบุฐานที่ใช้] และต้องมีมาตรการคุ้มครองข้อมูลที่เหมาะสมตามที่กฎหมายกำหนด"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การทำข้อมูลให้ไม่สามารถระบุตัวบุคคลได้"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้วิจัยต้องทำข้อมูลส่วนบุคคลให้อยู่ในรูปแบบที่ไม่สามารถระบุตัวบุคคลได้ (anonymization) หรือแฝงตัวบุคคล (pseudonymization) ก่อนนำไปใช้หรือเผยแพร่ผลการวิจัย เว้นแต่จำเป็นต้องใช้ข้อมูลที่ระบุตัวบุคคลได้เพื่อวัตถุประสงค์การวิจัยนั้นโดยมีมาตรการคุ้มครองเพิ่มเติม"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อจำกัดการใช้และเผยแพร่ผลการวิจัย"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้วิจัยต้องใช้ข้อมูลเฉพาะตามวัตถุประสงค์การวิจัยที่ตกลงกันเท่านั้น และผลการวิจัยที่เผยแพร่ต้องไม่สามารถระบุตัวเจ้าของข้อมูลส่วนบุคคลได้ ตามมาตรา 27"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "มาตรการความปลอดภัยของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้วิจัยต้องจัดให้มีมาตรการรักษาความมั่นคงปลอดภัยที่เหมาะสมตามมาตรา 37(2) และประกาศมาตรการความปลอดภัย พ.ศ. 2565 [โปรดระบุมาตรการที่ใช้]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การแจ้งเหตุละเมิดข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้วิจัยต้องแจ้งเหตุการละเมิดข้อมูลส่วนบุคคลที่เกี่ยวข้องกับข้อมูลที่ได้รับให้ผู้เปิดเผยข้อมูลทราบโดยไม่ชักช้าภายใน [โปรดระบุระยะเวลา]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การทำลายข้อมูลเมื่อสิ้นสุดโครงการวิจัย"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เมื่อสิ้นสุดโครงการวิจัยหรือข้อตกลงนี้ ผู้วิจัยต้องทำลายข้อมูลส่วนบุคคลที่ระบุตัวบุคคลได้ทั้งหมด เว้นแต่กฎหมายหรือจรรยาบรรณการวิจัยกำหนดให้ต้องเก็บไว้ต่อไป"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อมูลติดต่อเจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " อีเมล "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}, "en": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[DRAFT — this sample text must be reviewed and approved by Legal before real use]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Parties and roles"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This agreement is made between "}, {"type": "mergeField", "attrs": {"key": "org_name_en"}}, {"type": "text", "text": " (the \"Disclosing Party\") and [researcher/institution name] (the \"Researcher\") for disclosure of data for research purposes under sections 27 and 24(1) of the Personal Data Protection Act B.E. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Research purpose"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Disclosing Party agrees to disclose personal data to the Researcher solely for use in the academic or statistical research study [please specify the research project name and details]."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Legal basis for disclosure for research purposes"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Disclosure under this agreement relies on a legal basis for research or statistical purposes under section 24(1) or another relevant basis [please specify the basis used], with appropriate safeguards as required by law."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "De-identification of data"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Researcher shall anonymize or pseudonymize the personal data before use or publication of research results, unless identifiable data is necessary for the research purpose, in which case additional safeguards shall apply."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Restrictions on use and publication of results"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Researcher shall use the data only for the agreed research purpose, and published results shall not identify any data subject, under section 27."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Security measures"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Researcher shall implement appropriate security measures under section 37(2) and the 2022 Security Measures Notification. [Please specify the measures used]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Personal data breach notification"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Researcher shall notify the Disclosing Party of a personal data breach concerning the received data without delay, within [please specify a timeframe]."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Destruction of data at the end of the research project"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On completion of the research project or termination of this agreement, the Researcher shall destroy all identifiable personal data, unless law or research ethics requirements mandate further retention."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data Protection Officer contact"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Data Protection Officer: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " e-mail "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}}$j$::jsonb, 1, 'published');

